INSERT INTO MSF_UPLOAD_PHONE_INFO
(
    UPLOAD_PHONE_SRL_NO
    ,CRET_IP
    ,CRET_DT
    ,CRET_ID
    ,EID
    ,IMEI1
    ,IMEI2
    ,REQ_MODEL_NM
    ,MODEL_ID
    ,REQ_PHONE_SN
    ,UPLOAD_PHONE_IMG_NM
)
VALUES
(
    (SELECT MAX(UPLOAD_PHONE_SRL_NO)+1 FROM MSF_UPLOAD_PHONE_INFO)
    ,'127.0.0.1'
    ,now()
    ,'82311998'
    ,#{eid}
    ,#{imei1}
    ,#{imei2}
    ,#{reqModelNm}
    ,#{modelId}
    ,#{reqPhoneSn}
    ,#{uploadPhoneImgNm}
)
